export type GridServiceResolvePlaceData = {
    body?: never;
    path?: never;
    query?: {
        /**
         * Latitude in decimal degrees, -90 to 90. Requires `lng`.
         */
        lat?: number;
        /**
         * Longitude in decimal degrees, -180 to 180 (negative in California).
         * Requires `lat`.
         */
        lng?: number;
        /**
         * A US street address, geocoded with the Census geocoder. Include the city,
         * state or ZIP for a reliable match.
         */
        address?: string;
        /**
         * `BASE64` (default, legacy) or `OBJECT` for each place's `geometry`; same
         * as on `/api/v1/events`.
         */
        geometryFormat?: 'BASE64' | 'OBJECT';
    };
    url: '/api/v1/places:resolve';
};

export type GridServiceResolvePlaceErrors = {
    /**
     * INVALID_ARGUMENT: neither or both of lat+lng and address, only one of lat/lng, a value out of range, or an unknown geometryFormat.
     */
    400: RpcStatus;
    /**
     * NOT_FOUND: the geocoder found no match for the address (add city, state or ZIP).
     */
    404: RpcStatus;
    /**
     * UNAVAILABLE: the address geocoder is down; retry later or resolve by lat/lng.
     */
    503: RpcStatus;
    /**
     * An unexpected error response.
     */
    default: RpcStatus;
};

export type GridServiceResolvePlaceError = GridServiceResolvePlaceErrors[keyof GridServiceResolvePlaceErrors];

export type GridServiceResolvePlaceResponses = {
    /**
     * A successful response.
     */
    200: V1ResolvePlaceResponse;
};

export type GridServiceResolvePlaceResponse = GridServiceResolvePlaceResponses[keyof GridServiceResolvePlaceResponses];

